def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # Start of a new field
        if i == n:
            # End of line - add the last field if we've started parsing
            if i > 0 or not fields:  # Add empty field at end if line ends with comma
                if i == n and fields:  # Only add if we already have fields
                    if line[i-1] == ',':
                        fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - add single quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i < n and line[i] != ',':
                            # Closing quote not followed by comma or end
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < n and line[i] == ',':
                i += 1  # Skip the comma

    return fields

